import { readFile, writeFile } from 'node:fs/promises';

class Catalogs {
  static Root = new URL('../extension/', import.meta.url);
  static async run() {
    const en = JSON.parse(await readFile(new URL('_locales/en/messages.json', this.Root), 'utf8'));
    const zh = JSON.parse(await readFile(new URL('_locales/zh_CN/messages.json', this.Root), 'utf8'));
    await writeFile(new URL('locales.js', this.Root),
      '// Generated by scripts/locales.mjs from Chrome localization catalogs.\n' +
      `export class Catalogs {\n  static English = ${JSON.stringify(en)};\n  static Chinese = ${JSON.stringify(zh)};\n}\n`);
  }
}
await Catalogs.run();
